draw((1,0,0)--(0,1,0)--(0,0,1)--cycle);
draw((1,0,0)--(1/2,1/2,1/2));
draw((0,1,0)--(1/2,1/2,1/2));
draw((0,0,1)--(1/2,1/2,1/2));
